Office.onReady(() => {

    const generateButton = document.getElementById("generateButton");
    const reviseButton = document.getElementById("reviseButton");
    const insertButton = document.getElementById("insertButton");

    const generatedReply = document.getElementById("generatedReply");
    const instructionBox = document.getElementById("instruction");

    const item = Office.context.mailbox.item;


    // ==========================================
    // GENERATE REPLY
    // ==========================================

    generateButton.addEventListener("click", function () {

        generateButton.innerText = "Generating...";
        generateButton.disabled = true;


        item.body.getAsync(
            Office.CoercionType.Text,

            async function (result) {

                if (result.status !== Office.AsyncResultStatus.Succeeded) {

                    console.error(
                        "Could not read email:",
                        result.error
                    );

                    generateButton.innerText = "Generate Reply";
                    generateButton.disabled = false;

                    return;
                }


                const body = result.value;


                try {

                    const response = await fetch(
                        "https://outlookai-production.up.railway.app/generate",
                        {
                            method: "POST",

                            headers: {
                                "Content-Type": "application/json"
                            },

                            body: JSON.stringify({
                                body: body
                            })
                        }
                    );


                    const data = await response.json();


                    if (!response.ok) {

                        console.error(
                            "Backend error:",
                            data
                        );

                    } else {

                        generatedReply.value = data.reply;

                    }

                }

                catch (error) {

                    console.error(
                        "Could not connect to backend:",
                        error
                    );

                }


                generateButton.innerText = "Generate Reply";
                generateButton.disabled = false;

            }
        );

    });



    // ==========================================
    // APPLY INSTRUCTION
    // ==========================================

    reviseButton.addEventListener("click", async function () {

        const instruction = instructionBox.value.trim();
        const currentReply = generatedReply.value.trim();


        if (!currentReply) {
            return;
        }


        if (!instruction) {
            return;
        }


        reviseButton.innerText = "Applying...";
        reviseButton.disabled = true;


        try {

            const response = await fetch(
                "https://outlookai-production.up.railway.app/revise",
                {
                    method: "POST",

                    headers: {
                        "Content-Type": "application/json"
                    },

                    body: JSON.stringify({
                        reply: currentReply,
                        instruction: instruction
                    })
                }
            );


            const data = await response.json();


            if (!response.ok) {

                console.error(
                    "Backend error:",
                    data
                );

            } else {

                generatedReply.value = data.reply;

                instructionBox.value = "";

            }

        }

        catch (error) {

            console.error(
                "Could not connect to backend:",
                error
            );

        }


        reviseButton.innerText = "Apply Instruction";
        reviseButton.disabled = false;

    });



    // ==========================================
    // INSERT INTO OUTLOOK
    // ==========================================

    insertButton.addEventListener("click", function () {

        const reply = generatedReply.value.trim();


        if (!reply) {
            return;
        }


        insertButton.innerText = "Inserting...";
        insertButton.disabled = true;


        item.body.getTypeAsync(function (typeResult) {

            if (
                typeResult.status !==
                Office.AsyncResultStatus.Succeeded
            ) {

                console.error(
                    "Could not determine body type:",
                    typeResult.error
                );

                insertButton.innerText = "Insert Into Outlook";
                insertButton.disabled = false;

                return;
            }


            const bodyType = typeResult.value;

            let contentToInsert;


            if (
                bodyType ===
                Office.CoercionType.Html
            ) {

                contentToInsert =
                    "<div>" +
                    escapeHtml(reply)
                        .replace(/\n/g, "<br>") +
                    "</div><br>";

            } else {

                contentToInsert =
                    reply + "\n\n";

            }


            item.body.prependAsync(
                contentToInsert,
                {
                    coercionType: bodyType
                },

                function (result) {

                    if (
                        result.status !==
                        Office.AsyncResultStatus.Succeeded
                    ) {

                        console.error(
                            "Could not insert reply:",
                            result.error
                        );

                    }


                    insertButton.innerText = "Insert Into Outlook";
                    insertButton.disabled = false;

                }
            );

        });

    });



    // ==========================================
    // HTML SAFETY
    // ==========================================

    function escapeHtml(text) {

        return text
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");

    }

});